func upload(_ jpeg: Data, for userID: String) async throws -> URL {
    var request = URLRequest(url: baseURL.appendingPathComponent("users/\(userID)/avatar"))
    request.httpMethod = "PUT"
    request.setValue("image/jpeg", forHTTPHeaderField: "Content-Type")
    request.setValue("Bearer \(tokenStore.accessToken)", forHTTPHeaderField: "Authorization")

    return try await withCheckedThrowingContinuation { continuation in
        let task = session.uploadTask(with: request, from: jpeg) { data, response, error in
            if let error {
                continuation.resume(throwing: error)
                return
            }
            guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode),
                  let data,
                  let body = try? JSONDecoder().decode(AvatarResponse.self, from: data) else {
                continuation.resume(throwing: UploadError.badResponse)
                return
            }
            continuation.resume(returning: body.url)
        }
        task.resume()
    }
}

