import Foundation

final class ChunkUploader {
    private let session: URLSession
    init(session: URLSession = .shared) { self.session = session }

    private final class TaskBox: @unchecked Sendable {
        private let lock = NSLock()
        private var task: URLSessionUploadTask?
        private var cancelled = false
        func set(_ t: URLSessionUploadTask) {
            lock.lock(); defer { lock.unlock() }
            task = t
            if cancelled { t.cancel() }
        }
        func cancel() {
            lock.lock(); defer { lock.unlock() }
            cancelled = true
            task?.cancel()
        }
    }

    func send(chunk: Data, to url: URL) async throws -> Int {
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        let box = TaskBox()

        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (cont: CheckedContinuation<Int, Error>) in
                let task = session.uploadTask(with: req, from: chunk) { _, response, error in
                    if let error {
                        cont.resume(throwing: error)
                    } else {
                        cont.resume(returning: (response as? HTTPURLResponse)?.statusCode ?? -1)
                    }
                }
                box.set(task)
                task.resume()
            }
        } onCancel: {
            box.cancel()
        }
    }
}

