struct ClipExporter {
    let editor: VideoEditorSDK

    /// Renders the edited clip to a temp file.
    func export(project: EditProject) async throws -> URL {
        let output = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension("mp4")

        return try await withCheckedThrowingContinuation { continuation in
            editor.render(
                project,
                to: output,
                preset: .hd1080,
                progress: { fraction in
                    NotificationCenter.default.post(name: .exportProgress, object: fraction)
                    if fraction >= 1.0 {
                        // done — hand back the file as soon as possible
                        continuation.resume(returning: output)
                    }
                },
                completion: { error in
                    if let error {
                        continuation.resume(throwing: error)
                    } else {
                        continuation.resume(returning: output)
                    }
                }
            )
        }
    }
}

