@MainActor
final class PeripheralConnector: NSObject, CBCentralManagerDelegate {
    private let central: CBCentralManager
    private var connectContinuation: CheckedContinuation<CBPeripheral, Error>?

    init(central: CBCentralManager) {
        self.central = central
        super.init()
        central.delegate = self
    }

    func connect(_ peripheral: CBPeripheral) async throws -> CBPeripheral {
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { cont in
                connectContinuation = cont
                central.connect(peripheral, options: [CBConnectPeripheralOptionNotifyOnDisconnectionKey: true])
            }
        } onCancel: {
            Task { @MainActor in self.central.cancelPeripheralConnection(peripheral) }
        }
    }

    private func finish(_ result: Result<CBPeripheral, Error>) {
        guard let cont = connectContinuation else { return }
        connectContinuation = nil
        cont.resume(with: result)
    }

    nonisolated func centralManager(_ central: CBCentralManager, didConnect peripheral: CBPeripheral) {
        Task { @MainActor in finish(.success(peripheral)) }
    }

    nonisolated func centralManager(_ central: CBCentralManager, didFailToConnect peripheral: CBPeripheral, error: Error?) {
        Task { @MainActor in finish(.failure(error ?? CBError(.connectionFailed))) }
    }

    nonisolated func centralManager(_ central: CBCentralManager, didDisconnectPeripheral peripheral: CBPeripheral, error: Error?) {
        Task { @MainActor in finish(.failure(error ?? CancellationError())) }
    }

    nonisolated func centralManagerDidUpdateState(_ central: CBCentralManager) {}
}

