import Foundation

public final class RPCClient: @unchecked Sendable {
    private let socket: URLSessionWebSocketTask
    private let lock = NSLock()
    private var nextID = 0
    private var pending: [Int: CheckedContinuation<Data, Error>] = [:]

    public init(socket: URLSessionWebSocketTask) {
        self.socket = socket
    }

    public func call(_ method: String, params: Encodable) async throws -> Data {
        let id: Int = lock.withLock { nextID += 1; return nextID }
        let frame = try RPCFrame(id: id, method: method, params: params).encoded()

        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { cont in
                lock.withLock { pending[id] = cont }
                socket.send(.data(frame)) { [weak self] error in
                    guard let error else { return }
                    self?.take(id)?.resume(throwing: error)
                }
            }
        } onCancel: {
            take(id)?.resume(throwing: CancellationError())
        }
    }

    /// Called by the receive loop for every response frame.
    func deliver(id: Int, result: Result<Data, Error>) {
        take(id)?.resume(with: result)
    }

    private func take(_ id: Int) -> CheckedContinuation<Data, Error>? {
        lock.withLock { pending.removeValue(forKey: id) }
    }
}

