import Foundation

final class SyncWaitBox: @unchecked Sendable {
    private let lock = NSLock()
    private var token: NSObjectProtocol?
    private var continuation: CheckedContinuation<SyncSummary?, Never>?

    func arm(_ t: NSObjectProtocol, _ c: CheckedContinuation<SyncSummary?, Never>) {
        lock.withLock { token = t; continuation = c }
    }

    /// Task cancelled: stop observing and hand back nil.
    func cancel() {
        let (t, c) = lock.withLock { () -> (NSObjectProtocol?, CheckedContinuation<SyncSummary?, Never>?) in
            defer { token = nil; continuation = nil }
            return (token, continuation)
        }
        if let t { NotificationCenter.default.removeObserver(t) }
        c?.resume(returning: nil)
    }
}

enum SyncWaiter {
    /// Suspends until the sync engine posts `.syncDidFinish` for `scope`.
    static func waitForSync(scope: SyncScope) async -> SyncSummary? {
        let box = SyncWaitBox()
        return await withTaskCancellationHandler {
            await withCheckedContinuation { cont in
                let token = NotificationCenter.default.addObserver(
                    forName: .syncDidFinish, object: nil, queue: .main
                ) { note in
                    guard let summary = note.userInfo?["summary"] as? SyncSummary,
                          summary.scope == scope else { return }
                    cont.resume(returning: summary)
                }
                box.arm(token, cont)
            }
        } onCancel: {
            box.cancel()
        }
    }
}

