import Foundation
import AnalyticsSDK

struct AnalyticsFlusher {
    /// Flush queued events before the app suspends; gives up if the background task expires.
    func flush() async -> Bool {
        await withTaskCancellationHandler {
            await withCheckedContinuation { (cont: CheckedContinuation<Bool, Never>) in
                AnalyticsSDK.shared.flush { outcome in
                    switch outcome {
                    case .sent(let count):
                        Log.analytics.debug("flushed \(count) events")
                        cont.resume(returning: true)
                    case .nothingToSend:
                        cont.resume(returning: true)
                    case .failed(let error):
                        Log.analytics.error("flush failed: \(error.localizedDescription)")
                        cont.resume(returning: false)
                    case .cancelled:
                        cont.resume(returning: false)
                    }
                }
            }
        } onCancel: {
            // SDK calls the completion with .cancelled
            AnalyticsSDK.shared.cancelFlush()
        }
    }
}

