import Foundation
import Observation

@MainActor
@Observable
final class FeedViewModel {
    private(set) var posts: [Post] = []
    private(set) var isLoading = false
    private(set) var errorMessage: String?
    private var loadTask: Task<Void, Never>?
    private let api: FeedAPI

    init(api: FeedAPI) { self.api = api }

    func refresh() {
        loadTask?.cancel()
        loadTask = Task {
            isLoading = true
            defer { isLoading = false }
            do {
                let page = try await api.feed(cursor: nil) // URLSession async, cancellable
                try Task.checkCancellation()
                posts = page.items
                errorMessage = nil
            } catch is CancellationError {
                // superseded
            } catch {
                errorMessage = error.localizedDescription
            }
        }
    }

    func loadMore() async {
        guard let cursor = posts.last?.cursor, !isLoading else { return }
        isLoading = true
        defer { isLoading = false }
        if let page = try? await api.feed(cursor: cursor) {
            posts.append(contentsOf: page.items)
        }
    }
}

