import AuthenticationServices

@MainActor
final class OAuthCoordinator: NSObject, ASWebAuthenticationPresentationContextProviding {
    private var callbackContinuation: CheckedContinuation<URL, Error>?
    private var session: ASWebAuthenticationSession?
    private let config: OAuthConfig

    init(config: OAuthConfig) {
        self.config = config
    }

    func signIn(provider: OAuthProvider) async throws -> URL {
        let url = config.authorizeURL(for: provider, state: UUID().uuidString)
        return try await withCheckedThrowingContinuation { cont in
            self.callbackContinuation = cont
            let session = ASWebAuthenticationSession(url: url, callbackURLScheme: config.scheme) { [weak self] callbackURL, error in
                guard let self else { return }
                let cont = self.callbackContinuation
                self.callbackContinuation = nil
                if let callbackURL {
                    cont?.resume(returning: callbackURL)
                } else {
                    cont?.resume(throwing: error ?? OAuthError.cancelled)
                }
            }
            session.presentationContextProvider = self
            session.prefersEphemeralWebBrowserSession = provider.ephemeral
            self.session = session
            session.start()
        }
    }

    func presentationAnchor(for session: ASWebAuthenticationSession) -> ASPresentationAnchor {
        UIApplication.shared.connectedScenes
            .compactMap { ($0 as? UIWindowScene)?.keyWindow }
            .first ?? ASPresentationAnchor()
    }
}

