func readTag() async throws -> NFCNDEFMessage {
    guard NFCNDEFReaderSession.readingAvailable else { throw TagError.unsupported }
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { cont in
            readContinuation = cont
            let session = NFCNDEFReaderSession(delegate: self, queue: .main, invalidateAfterFirstRead: true)
            session.alertMessage = "Hold your card near the top of the phone."
            self.session = session
            session.begin()
        }
    } onCancel: {
        // invalidating reports didInvalidateWithError below, which resumes
        DispatchQueue.main.async { self.session?.invalidate() }
    }
}

func readerSession(_ session: NFCNDEFReaderSession, didInvalidateWithError error: Error) {
    readContinuation?.resume(throwing: error)
    readContinuation = nil
}

func readerSession(_ session: NFCNDEFReaderSession, didDetectNDEFs messages: [NFCNDEFMessage]) {
    let cont = readContinuation
    readContinuation = nil
    if let first = messages.first {
        cont?.resume(returning: first)
    } else {
        cont?.resume(throwing: TagError.emptyTag)
    }
}

