/// Only one caller at a time; a new request supersedes (and fails) the old one.
func nextCode() async throws -> String {
    if let previous = codeContinuation {
        codeContinuation = nil
        previous.resume(throwing: ScannerError.superseded)
    }
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { cont in
            codeContinuation = cont
            captureSession.startScanning()
        }
    } onCancel: {
        Task { @MainActor in
            self.captureSession.stopScanning()
            self.deliver(.failure(CancellationError()))
        }
    }
}

private func deliver(_ result: Result<String, Error>) {
    guard let cont = codeContinuation else { return }
    codeContinuation = nil
    captureSession.stopScanning()
    cont.resume(with: result)
}

