import HealthKit

private final class QueryState: @unchecked Sendable {
    private let lock = NSLock()
    private var resumed = false
    private var query: HKQuery?
    private var cancelled = false

    /// Returns true exactly once.
    func claimResume() -> Bool { lock.withLock { defer { resumed = true }; return !resumed } }
    func attach(_ q: HKQuery) -> Bool { lock.withLock { query = q; return !cancelled } }
    func cancel(on store: HKHealthStore) {
        let q = lock.withLock { () -> HKQuery? in cancelled = true; return query }
        if let q { store.stop(q) }
    }
}

struct StepCountReader {
    let store: HKHealthStore

    /// First statistics result for today; the update handler keeps firing, we only want one value.
    func todaySteps() async throws -> Double {
        let start = Calendar.current.startOfDay(for: .now)
        let predicate = HKQuery.predicateForSamples(withStart: start, end: nil)
        let state = QueryState()

        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { cont in
                let query = HKStatisticsCollectionQuery(
                    quantityType: HKQuantityType(.stepCount), quantitySamplePredicate: predicate,
                    options: .cumulativeSum, anchorDate: start,
                    intervalComponents: DateComponents(day: 1))
                let handle: (HKStatisticsCollectionQuery, HKStatisticsCollection?, Error?) -> Void = { q, collection, error in
                    guard state.claimResume() else { return } // fires repeatedly; resume only once
                    store.stop(q)
                    if let error { cont.resume(throwing: error); return }
                    let sum = collection?.statistics(for: start)?.sumQuantity()?.doubleValue(for: .count()) ?? 0
                    cont.resume(returning: sum)
                }
                query.initialResultsHandler = handle
                query.statisticsUpdateHandler = { q, _, collection, error in handle(q, collection, error) }
                if state.attach(query) {
                    store.execute(query)
                } else if state.claimResume() {
                    cont.resume(throwing: CancellationError())
                }
            }
        } onCancel: {
            // stopping the query delivers an error to the handler, which resumes once
            state.cancel(on: store)
        }
    }
}

