private var jobs: [PrintJobID: CheckedContinuation<Void, Error>] = [:]

func print(_ receipt: Receipt) async throws {
    let jobID = PrintJobID()
    try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { cont in
            jobs[jobID] = cont
            printer.enqueue(receipt.escpos, id: jobID)
        }
    } onCancel: {
        Task { @MainActor in
            self.printer.cancel(jobID) // reports .cancelled via didFinish below
        }
    }
}

func printer(_ printer: ReceiptPrinterDevice, didFinish jobID: PrintJobID, error: Error?) {
    guard let cont = jobs.removeValue(forKey: jobID) else { return }
    if let error { cont.resume(throwing: error) } else { cont.resume() }
}
